INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f03f633-773f-44bd-b4cb-9a99b7e992b0', 'e4045066-22ed-4a0f-b129-f8723fee7f64', 0, 'The CIA triad — Confidentiality (preventing unauthorized parties from reading or accessing sensitive data, protected through mechanisms like encryption and access control), Integrity (ensuring data is not improperly altered, whether accidentally or maliciously, protected through mechanisms like hashing, covered generally in a prior paper), and Availability (ensuring authorized users can actually access systems and data when legitimately needed, protected through mechanisms like redundancy and DDoS mitigation) — this is the single most foundational model nearly every other specific security control or concept covered across this project ultimately maps back to serving at least one of these three goals.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efd38184-3825-46fd-b7bc-55318795ad7a', 'e4045066-22ed-4a0f-b129-f8723fee7f64', 1, 'The AAA framework, since AAA is specifically defined as Confidentiality, Integrity, and Availability rather than Authentication, Authorization, and Accounting.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56d8ea4d-d8ba-4fc5-9980-fa601416cb5c', 'e4045066-22ed-4a0f-b129-f8723fee7f64', 2, 'Control categories, since control categories are specifically defined as the three foundational goals of Confidentiality, Integrity, and Availability.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62783a53-2133-4606-a99b-e3c7346f0abf', 'e4045066-22ed-4a0f-b129-f8723fee7f64', 3, 'Security controls serve no identifiable, common set of foundational goals; every individual control exists for an entirely unrelated, standalone purpose with no shared underlying model.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2207e39c-6f04-47dc-b2a7-c364915bfe47', '85aa63cc-fc29-4920-be92-967deb9d98e5', 0, 'Risk management strategies — avoidance (eliminating the risk entirely by choosing not to engage in the risky activity at all), transference (shifting the risk''s financial consequence to a third party, most commonly via cyber insurance, covered generally in a prior paper), mitigation (implementing a specific control to reduce the risk''s likelihood or impact, without eliminating the underlying risk entirely), and acceptance (covered generally in a prior paper, formally acknowledging the risk and choosing to proceed with no further action, ideally guided by the organization''s pre-established risk appetite, also covered generally in a prior paper) — together forming the complete, standard set of strategic response OPTIONS a risk decision genuinely chooses from.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff7cd59d-81c7-434a-8ed3-8a3da673df83', '85aa63cc-fc29-4920-be92-967deb9d98e5', 1, 'Control types, since control types are specifically defined as the four strategic risk-response options of avoidance, transference, mitigation, and acceptance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f19a0c1-f134-43d6-baa8-291e747607b9', '85aa63cc-fc29-4920-be92-967deb9d98e5', 2, 'ALE, since ALE is specifically defined as the four strategic risk-response options an organization chooses from, rather than a single calculated dollar figure.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d60c06e-f800-4b6a-8dad-ad43d7d6a11d', '85aa63cc-fc29-4920-be92-967deb9d98e5', 3, 'Organizations only ever have one single possible response to any identified risk; accepting, avoiding, transferring, or mitigating a specific risk are not genuinely distinct, separately available strategic choices.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98d7be55-462c-437a-877f-54876fb82fcb', '4b70439a-b5b2-4ea6-85ec-ab4a8e858753', 0, 'Cross-Site Scripting (XSS) — injecting malicious script into a web page that then executes in OTHER users'' browsers; Stored XSS PERMANENTLY saves the malicious script in the application''s backend (a database, a comment, a forum post), automatically executing for EVERY subsequent visitor who views that stored content with no further action needed from the attacker, making it genuinely more dangerous and wide-reaching; Reflected XSS instead embeds the malicious script directly in a crafted request (commonly a URL), executing ONLY for the specific victim who is tricked into clicking that particular malicious link, a narrower, one-victim-at-a-time attack requiring the attacker to actively distribute the crafted link — both are genuinely distinct from CSRF (covered generally in a prior paper), which forges a REQUEST using a victim''s existing session rather than injecting and EXECUTING attacker script code within a page.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('938d0e78-c3de-4323-b1a3-c3be903ec23c', '4b70439a-b5b2-4ea6-85ec-ab4a8e858753', 1, 'Reflected XSS is specifically defined as permanently storing malicious script in an application''s backend, while Stored XSS means embedding script in a single crafted URL for one victim — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fcfec1c-04f3-4bd2-9616-d8f5f462fee6', '4b70439a-b5b2-4ea6-85ec-ab4a8e858753', 2, 'Stored and Reflected XSS are two different names for the exact same vulnerability with no meaningful difference in persistence or how many victims it can actually affect.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ca5e7e1-bc19-452f-8249-5b5fa8ea0110', '4b70439a-b5b2-4ea6-85ec-ab4a8e858753', 3, 'A web application vulnerability can never cause a malicious script to actually execute within a visiting user''s own browser under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11844c1b-fdc1-41e0-a994-b75dbf9ff5db', 'a7ddbbb1-17ff-4c59-a65c-12f88aefd62d', 0, 'Session hijacking — stealing a legitimate, already-authenticated user''s session token/cookie and using it directly to impersonate that user''s active, already-logged-in session, entirely bypassing the need for the victim''s actual username or password, since the stolen token itself IS what the application actually uses to recognize an authenticated session; this is exactly why transmitting session tokens only over encrypted connections (HTTPS/TLS, connecting to the data-in-transit protection concept covered generally in prior papers) and setting appropriately short session token expiration/timeout values are standard, direct mitigations specifically reducing the window and opportunity for a token to actually be stolen and successfully reused.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38e00216-0cb6-44b1-93cc-9ee83ac947d6', 'a7ddbbb1-17ff-4c59-a65c-12f88aefd62d', 1, 'Credential stuffing, since credential stuffing is specifically defined as stealing an already-authenticated session token and using it to impersonate a victim, entirely bypassing the need for any username or password.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('306d6ba9-37c8-40d4-bc92-7bf213c75312', 'a7ddbbb1-17ff-4c59-a65c-12f88aefd62d', 2, 'A logic bomb, since logic bombs are specifically defined as stealing a legitimate user''s session token and using it to directly impersonate that user''s active session.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2580b695-aa17-4cc2-81ff-805245d537bf', 'a7ddbbb1-17ff-4c59-a65c-12f88aefd62d', 3, 'A stolen session token can never actually be used by an attacker to access an application, since every action always additionally requires re-entering the account''s actual username and password.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83d7aef1-8066-4f5c-96a1-73431921877c', 'c84b5910-13e2-4940-a339-f8bf846c5541', 0, 'Cryptojacking — secretly using a compromised system''s computing resources (CPU, and sometimes GPU) to mine cryptocurrency for the attacker''s own financial benefit, WITHOUT the resource owner''s knowledge or consent; genuinely distinct from ransomware (covered generally in a prior paper, which encrypts data and directly demands payment from the VICTIM) and from data-theft-focused attacks, since cryptojacking''s primary observable symptom is typically degraded performance and unexpectedly elevated compute costs, rather than any data being stolen, encrypted, or a ransom demand being made at all — the attacker profits directly from the STOLEN COMPUTE RESOURCES themselves, not from anything taken from or demanded of the victim organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88f47921-c641-4155-bf59-d4a061dc2341', 'c84b5910-13e2-4940-a339-f8bf846c5541', 1, 'Ransomware, since ransomware is specifically defined as secretly using a compromised system''s CPU resources to mine cryptocurrency, without encrypting any data or making a ransom demand.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7e20a89-19af-4a0d-8be9-fa9a9548613d', 'c84b5910-13e2-4940-a339-f8bf846c5541', 2, 'A worm, since worms are specifically defined as secretly using a compromised system''s CPU resources to mine cryptocurrency for the attacker''s own financial benefit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d90014b-cf87-47a9-8c1f-af357672054c', 'c84b5910-13e2-4940-a339-f8bf846c5541', 3, 'A compromised system''s computing resources can never actually be secretly used by an attacker for an unauthorized purpose like cryptocurrency mining.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1f486fe-b038-4be7-91a8-d9174d1bb444', 'b6458898-7da7-40e8-85d4-5a483f7c00c0', 0, 'A malicious insider (deliberately, knowingly causing harm — theft, sabotage — for personal gain or grievance), a negligent (or unintentional) insider (causing harm through genuine carelessness, a mistake, or a lack of awareness, with no actual malicious intent at all), and a compromised insider (an otherwise-legitimate account being controlled by an EXTERNAL attacker who obtained the credentials, meaning the actual human account holder may be entirely unaware their own account is being misused); this distinction matters because each sub-type genuinely calls for a different primary response — behavioral monitoring and legal/HR involvement for a malicious insider, security awareness training and process improvement for a negligent one, and credential-compromise incident response (connecting to UEBA, covered generally in a prior paper, for detecting anomalous behavior on a legitimate account) for a compromised one — treating all three identically risks a genuinely mismatched, less effective response.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa6e2287-1bdf-4fcf-91ad-ef18533eb454', 'b6458898-7da7-40e8-85d4-5a483f7c00c0', 1, 'These three scenarios describe the exact same insider threat sub-type under three different names, with no meaningful distinction in intent, cause, or appropriate response between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd8a3fd5-40a0-492e-8bbf-990f2f14d1c5', 'b6458898-7da7-40e8-85d4-5a483f7c00c0', 2, 'A CSIRT, since CSIRTs are specifically defined as the classification distinguishing malicious, negligent, and compromised insider threat sub-types.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0a4e648-1487-4ab4-a282-5eb70c3d846f', 'b6458898-7da7-40e8-85d4-5a483f7c00c0', 3, 'Insider threats can only ever be caused by deliberate, malicious intent; genuine accident or an externally-compromised legitimate account are not real, meaningful insider threat categories.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c7ded3a-4950-46a3-ba83-8dcc6f8f5425', 'da4232d7-ce93-44a2-8942-5cba1709df79', 0, 'Zero Trust pillars typically include: Identity (continuously verifying WHO is requesting access, connecting to authentication concepts covered generally elsewhere), Device (verifying the requesting DEVICE''s own security posture, connecting to NAC, covered generally in a prior paper), Network/Environment (segmenting and controlling network paths, connecting to micro-segmentation, covered generally in a prior paper), Application/Workload (securing the applications themselves, not just the network path to reach them), and Data (protecting the data itself directly, connecting to encryption and classification concepts covered generally elsewhere) — applying continuous verification across ALL of these distinct dimensions together, rather than "never trust, always verify" being applied only at the network-access layer alone.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d01169be-a6c7-4a4c-bf5d-6c5427959569', 'da4232d7-ce93-44a2-8942-5cba1709df79', 1, 'Zero Trust addresses only network access as a single, undifferentiated dimension, with no distinct additional pillars covering identity, device posture, application, or data separately.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d1f8d39-5b76-41ec-987e-8da77930220d', 'da4232d7-ce93-44a2-8942-5cba1709df79', 2, 'A CASB, since CASBs are specifically defined as the complete set of Zero Trust pillars spanning identity, device, network, application, and data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12cb4029-e8e6-4b12-a4b4-3675c2f76da9', 'da4232d7-ce93-44a2-8942-5cba1709df79', 3, 'Zero Trust is purely a marketing term with no genuine, structured architectural framework or distinct pillars underlying it.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50d68361-ee96-4bfa-adc4-69ad9f2bd658', 'c5966e31-7cb1-406b-af77-348a984a94fb', 0, 'A Secure Email Gateway (SEG) — a dedicated technology inspecting ALL inbound and outbound email traffic for phishing indicators, malicious attachments/links, and spam, filtering or flagging suspicious messages BEFORE they ever actually reach an employee''s inbox at all, providing a purpose-built TECHNICAL control layer that directly complements (rather than substitutes for) security awareness training (covered generally in a prior paper) — training helps employees correctly recognize and respond to whatever phishing attempts DO make it through, while a SEG specifically reduces the raw VOLUME of malicious email employees are exposed to reaching their inbox in the first place, a real, standard defense-in-depth layering of technical and human-focused controls working together.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d90db19-30bd-448b-a937-ef4860857ebb', 'c5966e31-7cb1-406b-af77-348a984a94fb', 1, 'A CASB, since CASBs are specifically defined as inspecting all inbound and outbound email traffic for phishing indicators and malicious attachments before delivery to an inbox.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1bb9f2f-0ec0-4ddb-a10d-a2640c86c258', 'c5966e31-7cb1-406b-af77-348a984a94fb', 2, 'NAC, since NAC''s core function is inspecting inbound and outbound email content for phishing indicators, malicious attachments, and spam before inbox delivery.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd24869f-042e-4813-bcd4-789d548e7962', 'c5966e31-7cb1-406b-af77-348a984a94fb', 3, 'No dedicated technology exists specifically for filtering email content before it reaches an inbox; only general employee awareness training can address phishing and malicious email at all.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34ca928a-d502-451b-9330-62066fed4068', '3cd679ce-2079-42e8-883f-dad08cc36087', 0, 'Virtual Desktop Infrastructure (VDI) — hosts desktop environments centrally, with employees accessing them remotely rather than data and applications living directly on their own physical device; the specific security benefit is centralization — since actual company data never leaves the centrally-controlled, centrally-secured data center environment at all, a lost or stolen physical employee device (or one infected with local malware) carries meaningfully lower real data-exposure risk than if that same device had been directly storing and processing sensitive company data itself, directly connecting to why BYOD security concerns (covered generally in a prior paper) are meaningfully reduced by a VDI approach specifically.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1f0a761-c87a-4ff4-b1a5-c29a7b56c0f0', '3cd679ce-2079-42e8-883f-dad08cc36087', 1, 'A CASB, since CASBs are specifically defined as centrally hosting a virtualized desktop environment that employees access remotely rather than running applications locally.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75928c8a-8221-4b02-b028-3a97fd73d0dd', '3cd679ce-2079-42e8-883f-dad08cc36087', 2, 'A honeynet, since honeynets are specifically defined as centrally hosting a virtualized desktop environment for legitimate employee remote access, rather than serving as a decoy for attackers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aafd69cf-1032-4844-9a74-8caebac629f7', '3cd679ce-2079-42e8-883f-dad08cc36087', 3, 'Centralizing desktop hosting and remote access provides no meaningful security benefit over data and applications running directly on each employee''s own physical device.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('259b3a57-8807-42d2-9572-62040a7a571b', '7690eaf1-1b77-41f7-b8ae-8bb22be54fc0', 0, 'Data masking — obscures a data value for DISPLAY/viewing purposes (showing only the last four digits, or replacing most characters with asterisks) specifically so a user can see enough of the value to perform their legitimate task (verifying a customer''s identity) without ever being shown the FULL sensitive value at all; this is genuinely different from tokenization (covered earlier — replacing the real value with a separately-stored, reversibly-lookupable substitute for later legitimate retrieval elsewhere) — masking is specifically about controlling what''s DISPLAYED to a given viewer''s eyes in a given context, not about creating a reversible substitute value usable in other systems, and the underlying full value may still exist unmasked elsewhere in the backend, simply not shown through THIS specific masked view.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('203d43cb-bfdd-4b2a-99f1-03001c8a1062', '7690eaf1-1b77-41f7-b8ae-8bb22be54fc0', 1, 'Tokenization, since tokenization is specifically defined as displaying only the last four digits of a sensitive value on screen, with the full value never displayed through that interface.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84dfb7db-837a-49f4-805c-96cc87e5ded3', '7690eaf1-1b77-41f7-b8ae-8bb22be54fc0', 2, 'Salting, since salting is specifically defined as obscuring a data value for display purposes by showing only its last four digits on screen.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('662c539f-9033-4630-bfec-c0cba1b09119', '7690eaf1-1b77-41f7-b8ae-8bb22be54fc0', 3, 'A user interface can never be designed to display only a partial, obscured version of a sensitive data value; any interface showing part of a value must always display the complete, full value as well.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('015314b0-75ce-4929-ae7a-00bd1dc91ad6', '086b02d0-2629-4b22-b4d6-a238c10cbee7', 0, 'STIX/TAXII — STIX (Structured Threat Information eXpression) is a standardized DATA FORMAT for describing threat intelligence (IOCs, attack patterns, threat actor information) in a consistent, machine-readable structure, while TAXII (Trusted Automated eXchange of Indicator Information) is the standardized TRANSPORT PROTOCOL for actually exchanging that STIX-formatted data between systems; together, they let threat intelligence (covered generally in a prior paper) from DIFFERENT vendors/sources be automatically consumed and correlated by a SIEM or other security tool in one consistent, standardized way, rather than requiring custom, one-off integration work for every single incompatible proprietary feed format.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1bda849-7ade-424f-bc4d-18413742eac8', '086b02d0-2629-4b22-b4d6-a238c10cbee7', 1, 'CVSS, since CVSS is specifically defined as the standardized data format and transport protocol for automatically sharing and consuming threat intelligence feeds across a SIEM.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3e2104a-4c02-4a81-89c1-c1a1c5791ed4', '086b02d0-2629-4b22-b4d6-a238c10cbee7', 2, 'OCSP, since OCSP is specifically defined as the standardized format for structuring and automatically exchanging threat intelligence IOCs between different vendors'' feeds.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d77c8716-96cf-45c6-a562-5d1728f65079', '086b02d0-2629-4b22-b4d6-a238c10cbee7', 3, 'No standardized format or protocol exists for sharing threat intelligence data between different vendors or tools; every feed source must always be manually and individually integrated with completely custom, one-off work.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a22f172-1ceb-4000-9c4b-88fccc1a7a3c', '1e36a480-6204-4b0a-8bd4-89c975eaaa2f', 0, 'Live acquisition (capturing data from a system WHILE it remains running/powered on, specifically capable of capturing genuinely volatile data — running processes, active network connections, and RAM contents — that would be permanently lost the instant the system is powered off, directly connecting to order of volatility, covered generally in a prior paper) and dead-box (or static) acquisition (examining a system''s storage AFTER it has been powered down, using a write blocker, covered generally in a prior paper, to safely image the drive without any risk of the running system''s own activity altering evidence during collection — capturing PERSISTENT disk data more safely and completely, but genuinely unable to capture volatile, running-state data that no longer exists once the system is off).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63fa4b3b-c41e-4231-9e25-cf8a995d1c38', '1e36a480-6204-4b0a-8bd4-89c975eaaa2f', 1, 'Dead-box acquisition is specifically defined as capturing volatile RAM contents and running processes from a still-powered-on system, while live acquisition means examining storage media only after the system has been powered down — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d7e3ff9-0730-477b-9cf9-8a469605fd07', '1e36a480-6204-4b0a-8bd4-89c975eaaa2f', 2, 'Live and dead-box forensic acquisition are two different names for the exact same evidence-collection method, with no meaningful difference in what data each approach can actually capture.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45ddef5c-3567-4135-8c73-23722f443ad5', '1e36a480-6204-4b0a-8bd4-89c975eaaa2f', 3, 'Forensic evidence can only ever be collected from a system after it has been completely powered down; capturing any evidence from a still-running, active system is not technically possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f800110-7cde-4077-9dd2-3dca9f443591', '99d52435-5d03-4001-98d7-003284c8c6d2', 0, 'A security champions program — embeds a specifically identified, interested, and trained individual WITHIN each development (or business) team, serving as that team''s local point of contact for security questions and informal review, genuinely SCALING a central security team''s limited capacity and expertise across the organization far more effectively than the central team alone attempting to directly review every single project itself, while also building genuine security awareness and ownership DIRECTLY within each individual team rather than security being perceived purely as an external, separate gatekeeping function imposed on developers from outside.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('582a8c9b-8d84-464c-8711-9f5feea4613a', '99d52435-5d03-4001-98d7-003284c8c6d2', 1, 'A CSIRT, since CSIRTs are specifically defined as embedding a trained security point of contact within each individual development team on an ongoing basis.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf62f9e3-b72e-49ce-8681-56b1a196ee5c', '99d52435-5d03-4001-98d7-003284c8c6d2', 2, 'A red team, since red teams are specifically defined as an embedded, ongoing point of contact within each development team for informal security code review.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c1d3bc8-b3b8-43e1-8abc-69191312dc42', '99d52435-5d03-4001-98d7-003284c8c6d2', 3, 'Embedding a security-trained individual within each individual development team provides no meaningful benefit over a small, centralized security team attempting to directly review every project themselves.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57b36931-0683-44f9-a393-ceccb18240d3', 'e67fab7a-3298-4d82-a535-0e2a122c5170', 0, 'Internal vulnerability scanning (performed from WITHIN the network, revealing what''s reachable from an already-inside position — relevant to insider threat, covered earlier this paper, or an attacker who has already achieved SOME initial foothold and is now moving laterally) and external vulnerability scanning (performed from OUTSIDE, over the public internet, revealing exactly what''s reachable and visible to an anonymous, unauthenticated external attacker with no prior access at all); a company genuinely needs BOTH perspectives because each answers a meaningfully different real-world question — external scanning shows the organization''s actual internet-facing attack surface as a genuine external attacker would first see it, while internal scanning reveals what''s reachable ONCE an attacker (or a malicious/negligent insider) already has SOME level of internal access, a genuinely different and complementary risk picture neither perspective alone fully captures.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a19b2b6-374b-4d05-bd06-dc6073dd0610', 'e67fab7a-3298-4d82-a535-0e2a122c5170', 1, 'External vulnerability scanning is specifically defined as being performed from within the internal network, while internal scanning means scanning from outside over the public internet — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3da4ce3-2679-41db-97b1-5b2c6a59ad4e', 'e67fab7a-3298-4d82-a535-0e2a122c5170', 2, 'Internal and external vulnerability scanning are two different names for the exact same scanning perspective, with no meaningful difference in what each approach actually reveals.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed8f072a-9015-4410-b2dc-a716b0434710', 'e67fab7a-3298-4d82-a535-0e2a122c5170', 3, 'A company only ever genuinely needs external vulnerability scanning; scanning from an internal network perspective provides no meaningfully distinct or additional real-world value.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86e8735f-01ff-4c8c-a2f8-ba69c6ba1b1e', '879f67de-65e0-48db-8bdc-ebbab4524b12', 0, 'An incident response retainer — a contract established with an external, specialized incident response firm BEFORE any actual incident occurs, pre-negotiating response-time commitments and general terms of engagement in advance, specifically so that expert, genuinely specialized help can be engaged and mobilized immediately once a real incident actually happens, rather than a company needing to find, vet, negotiate terms with, and onboard an unfamiliar firm for the very first time while already in the middle of an active, high-pressure crisis — directly valuable for organizations (particularly smaller or mid-sized ones) without the scale to justify a large, dedicated internal incident response capability of their own.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b484a7bb-8cb2-40a7-93c6-3343e4b38a8d', '879f67de-65e0-48db-8bdc-ebbab4524b12', 1, 'A CSIRT, since CSIRTs are specifically defined as a pre-arranged external contract negotiated in advance rather than an activated internal team.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86059e94-3fd9-4b9c-ba6c-69f4d77f0e06', '879f67de-65e0-48db-8bdc-ebbab4524b12', 2, 'A right-to-audit clause, since right-to-audit clauses are specifically defined as pre-negotiating response-time commitments with an external incident response firm before any incident occurs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('034830c1-c3fd-4477-b10d-54eaf47f5b5a', '879f67de-65e0-48db-8bdc-ebbab4524b12', 3, 'Engaging external, specialized incident response expertise is only ever possible during an already-active incident, with no ability to pre-arrange terms or response commitments in advance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('847159e9-2b34-46c6-b7db-66c96198be53', '5a1b3c50-87c7-4386-bfc8-ee91f5e3173d', 0, 'The MITRE ATT&CK framework — a standardized, publicly-available, and continuously updated knowledge base cataloging real-world adversary TACTICS (the attacker''s overall goal at a given stage, like "initial access" or "lateral movement") and specific TECHNIQUES (the concrete methods used to achieve that tactic) observed across actual real-world incidents, giving security teams a shared, standardized VOCABULARY and reference for classifying and communicating about observed attacker behavior, directly useful during both incident investigation (mapping what''s actually being observed to known technique patterns) and threat modeling (covered generally in a prior paper, informing which realistic techniques a proactive design-phase analysis should specifically consider).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d05fb2fc-a1d7-4e90-879e-9364310daac0', '5a1b3c50-87c7-4386-bfc8-ee91f5e3173d', 1, 'CVSS, since CVSS is specifically defined as the standardized catalog of real-world adversary tactics and techniques, rather than a vulnerability severity scoring methodology.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d90d6e4d-f23e-4380-a763-41d92bd7a195', '5a1b3c50-87c7-4386-bfc8-ee91f5e3173d', 2, 'STIX/TAXII, since STIX/TAXII is specifically defined as the standardized, publicly-available catalog of real-world adversary tactics and techniques, rather than a data format and transport protocol.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f186882-c900-4d65-8ac3-c03022cfdc77', '5a1b3c50-87c7-4386-bfc8-ee91f5e3173d', 3, 'No standardized, publicly-available catalog of real-world adversary tactics and techniques exists; every SOC analyst must always rely purely on their own individual, informal knowledge with no shared reference framework available.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a71313d7-52a0-488f-b481-797c24ae28f8', 'd9ec0ef5-c4df-450f-a281-f45ed0a952f0', 0, 'The NIST Cybersecurity Framework organizes activities into five core functions: Identify (understanding the organization''s assets, risks, and environment — connecting to gap analysis and risk registers, both covered generally in prior papers), Protect (implementing safeguards — the large majority of specific technical/administrative controls covered throughout this entire project map to this function), Detect (identifying that a security event is actually occurring — connecting to SIEM and threat hunting, both covered generally in prior papers), Respond (taking action once an incident is detected — connecting to incident response concepts covered generally throughout), and Recover (restoring capabilities and services after an incident — connecting to BCP/DR concepts covered generally in prior papers) — giving a comprehensive, structured way to organize and communicate about a cybersecurity program''s full lifecycle, from initial understanding through to eventual recovery.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a0bf875-3124-4224-9d0b-b7826e40e554', 'd9ec0ef5-c4df-450f-a281-f45ed0a952f0', 1, 'The NIST Cybersecurity Framework has no defined internal structure or core organizing categories of any kind; it exists purely as an unstructured, general recommendation to "be more secure" with no further internal organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1ad2e43-59e9-41a2-aa22-da9e8e8569fb', 'd9ec0ef5-c4df-450f-a281-f45ed0a952f0', 2, 'PCI-DSS, since PCI-DSS is specifically defined as the framework organizing cybersecurity activities into the Identify, Protect, Detect, Respond, and Recover core functions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2abc5b2e-deb5-46c3-8a11-ace541b0df27', 'd9ec0ef5-c4df-450f-a281-f45ed0a952f0', 3, 'FedRAMP, since FedRAMP is specifically defined as the framework organizing cybersecurity activities into the Identify, Protect, Detect, Respond, and Recover core functions.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5d85312-7e3e-47ce-8c25-73ce90839165', '5fa0116c-70db-47ec-9977-495bfc0f3817', 0, 'An indemnification clause — a contractual provision specifically allocating FINANCIAL LIABILITY between the parties, obligating one party (here, the vendor) to cover the other party''s (the customer''s) legal costs and damages if the FIRST party''s own failure — a product defect, a security breach caused by the vendor''s own negligence — directly causes the second party genuine harm; this is genuinely important vendor risk management (covered generally in a prior paper) leverage, since without a genuine indemnification clause, a company harmed by a vendor''s security failure could be left bearing the FULL financial consequence itself, with no contractual recourse against the vendor whose failure actually caused the harm in the first place.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad51d472-5e20-47ae-a742-94dcca54189d', '5fa0116c-70db-47ec-9977-495bfc0f3817', 1, 'A right-to-audit clause, since right-to-audit clauses are specifically defined as allocating financial liability for a vendor''s product defect or security failure, rather than granting the customer independent verification rights.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7b926ac-23ec-4689-a5f3-aa03741d202e', '5fa0116c-70db-47ec-9977-495bfc0f3817', 2, 'An MOU, since MOUs are specifically defined as a legally binding provision obligating a vendor to cover a customer''s legal costs and damages resulting from the vendor''s own security failure.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66146375-0a81-46ee-9ac6-33ab93a3fa6c', '5fa0116c-70db-47ec-9977-495bfc0f3817', 3, 'Vendor contracts can never contractually allocate financial liability for damages caused by one party''s own negligence or product defect to that same party.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db716d39-79e9-4c86-bab7-71e253d77cd2', 'd71f2d79-2eeb-4466-9a7d-4b10a0ce167a', 0, 'COPPA (the Children''s Online Privacy Protection Act) — a US federal law specifically requiring verifiable PARENTAL CONSENT before collecting personal information from children under 13, applying specifically to online services knowingly directed at or actually used by children in that age group; this is genuinely distinct in SCOPE from HIPAA (health information specifically, covered generally in a prior paper), GDPR (EU personal data broadly, regardless of age, covered generally in a prior paper), PCI-DSS (payment card data, covered generally in a prior paper), and SOX (financial reporting integrity, covered generally in a prior paper) — COPPA specifically targets the age/population of the data subject (children under 13) as its defining scope, a genuinely different organizing principle from every other regulation covered elsewhere, which are instead scoped by data TYPE, industry, or subject matter.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56ff096f-b7f5-4667-a6c5-6862298a47a4', 'd71f2d79-2eeb-4466-9a7d-4b10a0ce167a', 1, 'PCI-DSS, since PCI-DSS is specifically the US federal law requiring verifiable parental consent before collecting personal information from children under 13.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3012bef-6a2e-498b-a7d6-f722b47d0de5', 'd71f2d79-2eeb-4466-9a7d-4b10a0ce167a', 2, 'FedRAMP, since FedRAMP is specifically defined as the regulation requiring verifiable parental consent before collecting personal information from children under 13 on a website or mobile app.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd64bb7b-8a96-4913-a83e-c6916072c88c', 'd71f2d79-2eeb-4466-9a7d-4b10a0ce167a', 3, 'No US federal law imposes any special requirement specifically regarding the collection of personal information from children online; standard adult-focused privacy regulations always apply identically regardless of the data subject''s actual age.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('956bdb57-4c0e-4488-8388-b316af69964b', '7c193617-0714-4bfb-a1d5-0ccd12063ce6', 0, 'Mergers & Acquisitions (M&A) security due diligence — a specific application of the general due diligence concept (covered generally in a prior paper, pre-decision investigation before an action) to an acquisition specifically, systematically assessing a target company''s actual security posture, existing vulnerabilities, past breach/incident history, and any compliance gaps BEFORE the deal is finalized; timing matters enormously here because a security issue discovered BEFORE closing can still genuinely influence the deal — adjusting the purchase price, requiring specific remediation as a condition of closing, or in a severe enough case, the acquirer walking away from the deal entirely — options that are all essentially unavailable once the acquisition has already closed and the target company''s pre-existing security problems have effectively, unavoidably become the acquirer''s own.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70779672-7627-4b18-bf90-7f0ba8bec3d5', '7c193617-0714-4bfb-a1d5-0ccd12063ce6', 1, 'Due care, since due care is specifically defined as the pre-acquisition investigation of a target company''s security posture, rather than the ongoing, ROUTINE maintenance of security practices after a decision has already been made.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b134c82-9cff-4c8e-b12a-5008a717701e', '7c193617-0714-4bfb-a1d5-0ccd12063ce6', 2, 'A gap analysis, since gap analyses are specifically defined as the pre-acquisition assessment of a target company''s security posture, vulnerabilities, and breach history before a merger or acquisition deal is finalized.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e656f22b-63e7-4686-a9b5-ca42bfd5ebf7', '7c193617-0714-4bfb-a1d5-0ccd12063ce6', 3, 'A company''s own security team has no meaningful role in evaluating a prospective acquisition target''s security posture; this is always handled entirely by financial and legal teams alone, with no security-specific assessment ever performed.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
